using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed from
            // "Discriminator" to "$type". Preserve old name for compatibility
            // with existing 500K documents and direct SQL queries.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id format changed from "EntityType|Key"
            // to just "Key". Preserve old format for existing documents.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();

            // EF Core 9 removed vector/index model-level config via HasIndex
            // for Cosmos; use indexing policy or raw SQL instead if needed.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

